template.solver:
def solve(n):
    best = -1
    for A in range(1, 10):
        for L in range(10):
            for M in range(10):
                for T in range(10):
                    if A == L or A == M or A == T or L == M or L == T or M == T:
                        continue
                    alma = 1000 * A + 100 * L + 10 * M + A
                    ata = 100 * A + 10 * T + A
                    if alma - ata == n:
                        if T > best:
                            best = T
    return best
